'use strict';

import { apiCallsMixin, copyToClipboard, createToast, getUrlParameter, initCommonUI, logErrorInConsole, registerPageSpecificLoginUIUpdates } from "./common.v2.js";

// Plot types generated by get_domino_plots.cgi, in display (and tab) order.  "tab" is the short tab label.
const PLOT_TYPES = {
    dot_tf: {
        title: "Dot Plot - Selected TF",
        tab: "Dot: Selected TF",
        description: "Geometric mean of ligand and receptor expression for each ligand/receptor and sending/receiving cluster pair involving the selected TF."
    },
    dot_clusters: {
        title: "Dot Plot - Selected Clusters",
        tab: "Dot: Selected clusters",
        description: "Geometric mean of ligand and receptor expression for each ligand/receptor pair between the selected sending and receiving clusters."
    },
    dot_clusters_filtered: {
        title: "Dot Plot - Selected Clusters, Thresholded",
        tab: "Dot: Thresholded clusters",
        description: "Geometric mean of ligand and receptor expression for each ligand/receptor pair between the selected sending and receiving clusters, but keeping only ligand/receptor pairs whose expression range or highest expression exceeds the chosen thresholds."
    },
    river_tf: {
        title: "River Plot - Selected TF",
        tab: "River: Selected TF",
        description: "Signalling from sending clusters through ligands and receptors to receiving clusters, for the selected TF."
    },
    river_ligand: {
        title: "River Plot - Selected Ligand",
        tab: "River: Selected ligand",
        description: "Signalling from sending clusters through receptors and TFs to receiving clusters, for the selected ligand."
    },
    river_receptor: {
        title: "River Plot - Selected Receptor",
        tab: "River: Selected receptor",
        description: "Signalling from sending clusters through ligands and TFs to receiving clusters, for the selected receptor."
    },
    river_selected: {
        title: "River Plot - Custom Selection",
        tab: "River: Custom selection",
        description: "Full signalling pathways matching all of the river plot options (clusters, ligands, receptors and TFs)."
    },
    river_selected_notf: {
        title: "River Plot - Custom Selection, without TFs",
        tab: "River: Custom, without TFs",
        description: "Full signalling pathways matching all of the river plot options (clusters, ligands, receptors), with TFs omitted (and TF selections ignored), to simplify plots spanning many parameters."
    },
};

// Parameter select boxes.  "param" is the name used by the CGI and in the page URL,
//  and "options" is the key of the values to populate from get_domino_options.cgi
const PARAMETER_SELECTS = [
    { id: "selected-tf", param: "selected_tf", options: "tfs", multiple: false },
    { id: "selected-ligand", param: "selected_ligand", options: "ligands", multiple: false },
    { id: "selected-receptor", param: "selected_receptor", options: "receptors", multiple: false },
    // Dot plot options
    { id: "dot-sending-clusters", param: "sending_clusters", options: "sending_clusters", multiple: true },
    { id: "dot-receiving-clusters", param: "receiving_clusters", options: "receiving_clusters", multiple: true },
    // River plot options
    { id: "river-sending-clusters", param: "selected_sending", options: "sending_clusters", multiple: true },
    { id: "river-ligands", param: "selected_ligands", options: "ligands", multiple: true },
    { id: "river-receptors", param: "selected_receptors", options: "receptors", multiple: true },
    { id: "river-tfs", param: "selected_tfs", options: "tfs", multiple: true },
    { id: "river-receiving-clusters", param: "selected_receiving", options: "receiving_clusters", multiple: true },
];

const fileSelector = document.getElementById("domino-file-selector");
const showVisualizationsButton = document.getElementById("show-visualizations");
const copyShareLinkButton = document.getElementById("copy-share-link");
const expRangeThreshold = document.getElementById("exp-range-threshold");
const expMaxThreshold = document.getElementById("exp-max-threshold");
const riverApplyThresholds = document.getElementById("river-apply-thresholds");
const dotSizeScale = document.getElementById("dot-size-scale");
const dotWhiteBackground = document.getElementById("dot-white-background");

// NiceSelect instances, keyed by select element ID
const niceSelects = {};

// Parameters the currently shown plots were generated with
let renderedPlotParams = null;

// Selections passed via the URL, applied once the selected file's options are loaded
let urlSelections = {};

fileSelector.addEventListener("change", async () => {
    await loadDominoOptions(fileSelector.value);
});

// The magnifying glass opens the DominoSignal output list
document.getElementById("open-domino-file-selector").addEventListener("click", () => {
    fileSelector.focus();
    try {
        fileSelector.showPicker();
    } catch (error) {
        // showPicker() is unsupported in some older browsers; the focused select can still be opened from the keyboard
        console.info("Could not open the DominoSignal output list", error);
    }
});

// Each parameter section's arrow expands or collapses its body
for (const toggle of document.querySelectorAll(".section-toggle")) {
    toggle.addEventListener("click", () => {
        const body = document.getElementById(toggle.getAttribute("aria-controls"));
        const icon = toggle.querySelector("i");
        const isCollapsing = !body.classList.contains("is-hidden");

        body.classList.toggle("is-hidden", isCollapsing);
        icon.classList.toggle("mdi-chevron-up", !isCollapsing);
        icon.classList.toggle("mdi-chevron-down", isCollapsing);
        toggle.setAttribute("aria-expanded", String(!isCollapsing));
        toggle.title = isCollapsing ? "Expand section" : "Collapse section";
    });
}

// Show the dot size slider's value as a percentage of the default size
const updateDotSizeScaleLabel = () => {
    document.getElementById("dot-size-scale-value").textContent = `${Math.round(Number(dotSizeScale.value) * 100)}%`;
};
dotSizeScale.addEventListener("input", updateDotSizeScaleLabel);

// Arrow keys (and Home/End) move between plot tabs
document.querySelector("#plot-tabs ul").addEventListener("keydown", async (event) => {
    const tabs = Array.from(document.querySelectorAll("#plot-tabs li"));
    const current = tabs.findIndex((tab) => tab.contains(document.activeElement));
    const targets = { ArrowRight: current + 1, ArrowLeft: current - 1, Home: 0, End: tabs.length - 1 };

    if (current === -1 || !(event.key in targets)) {
        return;
    }

    event.preventDefault();
    const target = tabs[(targets[event.key] + tabs.length) % tabs.length];
    target.querySelector("a").focus();
    await selectPlotTab(target);
});

// Copy the sending/receiving cluster selections between the dot plot and river plot options
document.getElementById("copy-clusters-to-river").addEventListener("click", () => {
    copyClusterSelections("dot", "river");
});

document.getElementById("copy-clusters-to-dot").addEventListener("click", () => {
    copyClusterSelections("river", "dot");
});

// Swap the dot plot's sending and receiving cluster selections
document.getElementById("swap-dot-clusters").addEventListener("click", () => {
    swapClusterSelections("dot");
});

// Copy a link that reopens this page with the current selections
copyShareLinkButton.addEventListener("click", async () => {
    const params = buildPlotParams();

    if (!validatePlotParams(params)) {
        return;
    }

    if (await copyToClipboard(buildShareURL(params))) {
        createToast("Share link copied to clipboard.", "is-success");
    } else {
        createToast("Failed to copy share link to clipboard.", "is-danger");
    }
});

showVisualizationsButton.addEventListener("click", async (event) => {
    const currentTarget = event.currentTarget;
    const params = buildPlotParams();

    if (!validatePlotParams(params)) {
        return;
    }

    currentTarget.classList.add("is-loading");
    document.getElementById("result-panel-initial-notification").classList.add("is-hidden");
    document.getElementById("result-panel-loader").classList.remove("is-hidden");
    clearPlots();

    try {
        const data = await apiCallsMixin.fetchDominoPlots(params);

        if (data.success < 1) {
            createToast(data.message || "There was an error generating the plots");
            return;
        }

        // Plot downloads regenerate plots from the parameters they were drawn with, not the current form
        renderedPlotParams = params;
        await renderPlots(data, params.plots);
    } catch (error) {
        logErrorInConsole(error);
        createToast("There was an error generating the plots");
    } finally {
        currentTarget.classList.remove("is-loading");
        document.getElementById("result-panel-loader").classList.add("is-hidden");
    }
});

/**
 * Fetches the available DominoSignal output files and populates the file selector.
 */
const fetchDominoFiles = async () => {
    try {
        const data = await apiCallsMixin.fetchDominoOptions();
        fileSelector.replaceChildren();

        if (!data.files?.length) {
            fileSelector.appendChild(new Option("No DominoSignal outputs available", ""));
            return;
        }

        fileSelector.appendChild(new Option("Choose a DominoSignal output", ""));
        for (const filename of data.files) {
            fileSelector.appendChild(new Option(filename, filename));
        }
    } catch (error) {
        logErrorInConsole(error);
        createToast("There was an error fetching the DominoSignal outputs");
    }
};

/**
 * Fetches the selectable TFs, ligands, receptors and clusters for a DominoSignal output
 * and populates the parameter select boxes.
 *
 * @param {string} filename - The DominoSignal .parquet file.
 */
const loadDominoOptions = async (filename) => {
    const parametersContainer = document.getElementById("parameters-c");
    showVisualizationsButton.disabled = true;
    copyShareLinkButton.disabled = true;
    document.getElementById("dataset-info-c").classList.add("is-hidden");

    if (!filename) {
        parametersContainer.classList.add("is-hidden");
        return;
    }

    showVisualizationsButton.classList.add("is-loading");
    try {
        const data = await apiCallsMixin.fetchDominoOptions(filename);

        if (data.success < 1) {
            createToast(data.message || "There was an error loading this DominoSignal output");
            parametersContainer.classList.add("is-hidden");
            return;
        }

        for (const config of PARAMETER_SELECTS) {
            populateParameterSelect(config, data.options[config.options], urlSelections[config.param] || []);
        }
        urlSelections = {};

        renderDatasetInfo(data.dataset_info);
        parametersContainer.classList.remove("is-hidden");
        showVisualizationsButton.disabled = false;
        copyShareLinkButton.disabled = false;
    } catch (error) {
        logErrorInConsole(error);
        createToast("There was an error loading this DominoSignal output");
    } finally {
        showVisualizationsButton.classList.remove("is-loading");
    }
};

/**
 * Shows the details of the paper and dataset behind the chosen output (from its matching .json file):
 *
 *   "Title", Author, Year
 *   DOI: ... | PMID: ...
 *   gEAR Dataset: ...
 *   Description: ...
 *
 * Optional details that weren't provided show as N/A.  If there is no .json file, or the title,
 * author or year is missing, a disclaimer is shown instead.
 *
 * @param {Object|null} info - The dataset_info from get_domino_options.cgi.
 */
const renderDatasetInfo = (info) => {
    const hasCitation = Boolean(info?.title && info?.author && info?.year);

    document.getElementById("dataset-info-details").classList.toggle("is-hidden", !hasCitation);
    document.getElementById("dataset-info-missing").classList.toggle("is-hidden", hasCitation);
    document.getElementById("dataset-info-c").classList.remove("is-hidden");

    if (!hasCitation) {
        return;
    }

    // Text is set with textContent/text nodes, never as HTML, since it comes from an uploaded file
    document.getElementById("dataset-info-citation").textContent = `"${info.title}", ${info.author}, ${info.year}`;

    const doiUrl = /^https?:\/\//i.test(info.doi || "") ? info.doi : `https://doi.org/${encodeURI(info.doi || "")}`;
    const pmidUrl = /^\d+$/.test(info.pmid || "") ? `https://pubmed.ncbi.nlm.nih.gov/${info.pmid}/` : null;
    document.getElementById("dataset-info-ids").replaceChildren(
        createDatasetInfoLabel("DOI"), " ", createDatasetInfoValue(info.doi, doiUrl),
        " | ", createDatasetInfoLabel("PMID"), " ", createDatasetInfoValue(info.pmid, pmidUrl),
    );

    document.getElementById("dataset-info-url").replaceChildren(
        createDatasetInfoLabel("gEAR Dataset"), " ", createDatasetInfoValue(info.gear_url, toWebUrl(info.gear_url)),
    );

    document.getElementById("dataset-info-description").replaceChildren(
        createDatasetInfoLabel("Description"), " ", createDatasetInfoValue(info.description, null),
    );
};

/**
 * A bold label (with its colon) for a dataset detail.
 *
 * @param {string} label - The detail's name.
 * @returns {HTMLElement} - The label element.
 */
const createDatasetInfoLabel = (label) => {
    const labelElt = document.createElement("strong");
    labelElt.textContent = `${label}:`;
    return labelElt;
};

/**
 * A dataset detail for display: a link if a URL is given, plain text otherwise, or "N/A" if not provided.
 *
 * @param {string|null} value - The detail.
 * @param {string|null} url - Where the detail should link to, if anywhere.
 * @returns {Node} - The element or text node to show.
 */
const createDatasetInfoValue = (value, url) => {
    if (!value) {
        return document.createTextNode("N/A");
    }
    if (!url) {
        return document.createTextNode(value);
    }

    const link = document.createElement("a");
    link.href = url;
    link.target = "_blank";
    link.rel = "noopener noreferrer";
    link.textContent = value;
    return link;
};

/**
 * Converts a web address to a full http(s) URL (e.g. "umgear.org" -> "https://umgear.org").
 *
 * @param {string|null} address - The web address.
 * @returns {string|null} - The URL, or null if it isn't a valid web address (e.g. another scheme like "javascript:").
 */
const toWebUrl = (address) => {
    if (!address) {
        return null;
    }

    try {
        const url = new URL(/^[a-z][a-z0-9+.-]*:/i.test(address) ? address : `https://${address}`);
        return ["http:", "https:"].includes(url.protocol) ? url.href : null;
    } catch {
        return null;
    }
};

/**
 * Fills a parameter select box with options and (re)binds its searchable NiceSelect.
 *
 * @param {Object} config - Entry from PARAMETER_SELECTS.
 * @param {string[]} values - Option values.
 * @param {string[]} selectedValues - Values to preselect.
 */
const populateParameterSelect = (config, values, selectedValues) => {
    const select = document.getElementById(config.id);
    select.replaceChildren();

    // Single selections can be left unset
    if (!config.multiple) {
        select.appendChild(new Option("None", ""));
    }

    for (const value of values) {
        const option = new Option(value, value);
        // NiceSelect tracks selections via the "selected" attribute
        if (selectedValues.includes(value)) {
            option.setAttribute("selected", "");
        }
        select.appendChild(option);
    }

    // NiceSelect rebuilds the selected item chips whenever the selection changes
    if (config.multiple && !niceSelects[config.id]) {
        select.addEventListener("change", () => addChipRemoveButtons(niceSelects[config.id]));
    }

    bindNiceSelect(select);
};

/**
 * Binds a searchable NiceSelect to a select box, replacing any existing one so it reflects
 * the select's current options and selections.
 *
 * NiceSelect's own update() is avoided, as afterwards its selected options no longer match
 * the rendered dropdown items, which breaks deselecting.
 *
 * @param {HTMLSelectElement} select - The select box.
 */
const bindNiceSelect = (select) => {
    niceSelects[select.id]?.destroy();
    niceSelects[select.id] = NiceSelect.bind(select, {
        searchable: true,
        showSelectedItems: true,
    });

    if (select.multiple) {
        addChipRemoveButtons(niceSelects[select.id]);
    }
};

/**
 * Adds a remove ("x") button to each selected item chip of a multiple NiceSelect, so
 * values can be deselected without opening the dropdown.
 *
 * @param {Object} niceSelect - The NiceSelect instance.
 */
const addChipRemoveButtons = (niceSelect) => {
    const chips = niceSelect.dropdown.querySelectorAll(".multiple-options .current");

    // Chips are rendered in the same order as the selected options
    chips.forEach((chip, index) => {
        const selectedOption = niceSelect.selectedOptions[index];
        const removeButton = document.createElement("span");
        removeButton.classList.add("chip-remove", "mdi", "mdi-close");
        removeButton.setAttribute("role", "button");
        removeButton.dataset.testid = "chip-remove";
        removeButton.setAttribute("aria-label", `Remove ${selectedOption.data.text}`);

        removeButton.addEventListener("click", (event) => {
            // Keep the click from opening the dropdown
            event.stopPropagation();
            // Deselect as if the item was clicked in the dropdown list
            selectedOption.element.dispatchEvent(new MouseEvent("click", { bubbles: false }));
        });

        chip.appendChild(removeButton);
    });
};

/**
 * Gets the current value(s) of a parameter select box.
 *
 * @param {Object} config - Entry from PARAMETER_SELECTS.
 * @returns {string|string[]} - The selected value, or array of values for multiple selects.
 */
const getParameterSelectValue = (config) => {
    const select = document.getElementById(config.id);

    if (config.multiple) {
        return Array.from(select.querySelectorAll("option[selected]")).map((option) => option.value);
    }
    return select.value;
};

/**
 * Replaces the selected values of a multiple parameter select box.
 *
 * @param {string} id - ID of the select element.
 * @param {string[]} values - Values to select; any others are deselected.
 */
const setMultipleSelectValues = (id, values) => {
    const select = document.getElementById(id);

    // NiceSelect tracks selections via the "selected" attribute
    for (const option of select.options) {
        option.toggleAttribute("selected", values.includes(option.value));
    }

    bindNiceSelect(select);
};

/**
 * Copies the sending and receiving cluster selections from one section's selects to the other's.
 *
 * @param {string} from - Prefix of the select IDs to copy from ("dot" or "river").
 * @param {string} to - Prefix of the select IDs to copy to ("dot" or "river").
 */
const copyClusterSelections = (from, to) => {
    for (const direction of ["sending", "receiving"]) {
        const config = PARAMETER_SELECTS.find((c) => c.id === `${from}-${direction}-clusters`);
        setMultipleSelectValues(`${to}-${direction}-clusters`, getParameterSelectValue(config));
    }
};

/**
 * Swaps a section's sending and receiving cluster selections.  Sending and receiving clusters are
 * listed separately, so a cluster only available on one side stays where it is, and is reported.
 *
 * @param {string} prefix - Prefix of the select IDs ("dot" or "river").
 */
const swapClusterSelections = (prefix) => {
    const sendingId = `${prefix}-sending-clusters`;
    const receivingId = `${prefix}-receiving-clusters`;
    const getConfig = (id) => PARAMETER_SELECTS.find((c) => c.id === id);
    const getOptionValues = (id) => Array.from(document.getElementById(id).options).map((option) => option.value);

    const sending = getParameterSelectValue(getConfig(sendingId));
    const receiving = getParameterSelectValue(getConfig(receivingId));
    const sendingOptions = getOptionValues(sendingId);
    const receivingOptions = getOptionValues(receivingId);

    const stuckSending = sending.filter((value) => !receivingOptions.includes(value));
    const stuckReceiving = receiving.filter((value) => !sendingOptions.includes(value));

    setMultipleSelectValues(sendingId, [...receiving.filter((value) => sendingOptions.includes(value)), ...stuckSending]);
    setMultipleSelectValues(receivingId, [...sending.filter((value) => receivingOptions.includes(value)), ...stuckReceiving]);

    const notMoved = [...stuckSending, ...stuckReceiving];
    if (notMoved.length > 0) {
        createToast(`Some clusters aren't available on the other side, so were left in place: ${notMoved.join(", ")}`, "is-warning");
    }
};

/**
 * Builds the get_domino_plots.cgi parameters from the current form state.  Unset
 * parameters are omitted.
 *
 * @returns {Object} - The plot parameters.
 */
const buildPlotParams = () => {
    const params = {
        filename: fileSelector.value,
        plots: Array.from(document.querySelectorAll(".plot-type-toggle:checked")).map((elt) => elt.value),
        exp_range_threshold: expRangeThreshold.value,
        exp_max_threshold: expMaxThreshold.value,
    };

    if (riverApplyThresholds.checked) {
        params.river_apply_thresholds = 1;
    }

    // Advanced plotting options
    params.dot_size_scale = dotSizeScale.value;
    if (dotWhiteBackground.checked) {
        params.dot_white_background = 1;
    }

    for (const config of PARAMETER_SELECTS) {
        const value = getParameterSelectValue(config);
        if (value.length > 0) {
            params[config.param] = value;
        }
    }

    return params;
};

/**
 * Validates the plot parameters, notifying the user of any problems.
 *
 * @param {Object} params - The plot parameters.
 * @returns {boolean} - True if the parameters are valid.
 */
const validatePlotParams = (params) => {
    if (!params.filename) {
        createToast("Please select a DominoSignal output to proceed");
        return false;
    }

    if (params.plots.length === 0) {
        createToast("Please select at least one plot to proceed");
        return false;
    }

    for (const threshold of [params.exp_range_threshold, params.exp_max_threshold]) {
        if (threshold === "" || isNaN(Number(threshold)) || Number(threshold) < 0) {
            createToast("Dot plot thresholds must be non-negative numbers");
            return false;
        }
    }

    return true;
};

/**
 * Renders the requested plots as tabs, one per plot, in PLOT_TYPES order.  Plots that couldn't
 * be generated for the current selections show the reason instead (and a warning icon on the tab).
 *
 * Each plot is drawn when its tab is first opened, since Plotly can't size plots in hidden panes.
 *
 * @param {Object} data - Response from get_domino_plots.cgi.
 * @param {string[]} plotTypes - The requested plot types.
 */
const renderPlots = async (data, plotTypes) => {
    const tabList = document.querySelector("#plot-tabs ul");
    const panes = document.getElementById("plot-tab-panes");
    const tabTemplate = document.getElementById("tmpl-plot-tab");
    const cardTemplate = document.getElementById("tmpl-plot-card");
    const orderedPlotTypes = Object.keys(PLOT_TYPES).filter((type) => plotTypes.includes(type));

    for (const plotType of orderedPlotTypes) {
        const paneId = `plot-pane-${plotType}`;
        const tabId = `plot-tab-${plotType}`;

        const card = cardTemplate.content.cloneNode(true).querySelector(".plot-card");
        card.id = paneId;
        card.dataset.plotType = plotType;
        card.dataset.testid = `plot-pane-${plotType}`;
        card.setAttribute("aria-labelledby", tabId);
        card.querySelector(".plot-card-title").textContent = PLOT_TYPES[plotType].title;
        card.querySelector(".plot-card-description").textContent = PLOT_TYPES[plotType].description;
        panes.appendChild(card);

        const tab = tabTemplate.content.cloneNode(true).querySelector("li");
        const tabLink = tab.querySelector("a");
        tab.dataset.tab = paneId;
        tab.dataset.testid = `plot-tab-${plotType}`;
        tabLink.id = tabId;
        tabLink.setAttribute("aria-controls", paneId);
        tab.querySelector(".plot-tab-label").textContent = PLOT_TYPES[plotType].tab;
        tab.addEventListener("click", () => selectPlotTab(tab));
        tabList.appendChild(tab);

        const plot = data.plots[plotType];
        if (plot) {
            pendingPlots.set(paneId, plot);
        } else {
            showPlotCardMessage(card, data.messages[plotType] || "This plot could not be generated");
        }
    }

    document.getElementById("result-panel-grid").classList.remove("is-hidden");

    // Open the first tab with a plot, rather than one only showing why its plot couldn't be generated
    const tabs = Array.from(tabList.querySelectorAll("li"));
    await selectPlotTab(tabs.find((tab) => pendingPlots.has(tab.dataset.tab)) || tabs[0]);
};

// Plots not yet drawn, keyed by pane ID.  Each is drawn when its tab is first opened.
const pendingPlots = new Map();

/**
 * Shows a plot tab's pane, hiding the others, and draws its plot if not drawn yet.
 *
 * @param {HTMLLIElement} tab - The tab to select.
 */
const selectPlotTab = async (tab) => {
    for (const item of document.querySelectorAll("#plot-tabs li")) {
        const isSelected = item === tab;
        const link = item.querySelector("a");
        item.classList.toggle("is-active", isSelected);
        link.setAttribute("aria-selected", String(isSelected));
        link.tabIndex = isSelected ? 0 : -1;
        document.getElementById(item.dataset.tab).classList.toggle("is-hidden", !isSelected);
    }

    const card = document.getElementById(tab.dataset.tab);
    const plotElt = card.querySelector(".plot-card-plot");
    const plot = pendingPlots.get(card.id);

    if (!plot) {
        // Already drawn; resize in case the window changed while this tab was hidden
        if (plotElt.classList.contains("js-plotly-plot")) {
            Plotly.Plots.resize(plotElt);
        }
        return;
    }

    // A plot that fails to draw only affects its own tab
    pendingPlots.delete(card.id);
    try {
        await Plotly.newPlot(plotElt, plot.data, plot.layout, {
            responsive: true,
            displaylogo: false,
            // Replace the camera button with one that downloads a PNG, or a PDF if chosen in the advanced plotting options
            modeBarButtonsToRemove: ["toImage"],
            modeBarButtonsToAdd: [{
                name: "downloadPlot",
                title: "Download plot",
                icon: Plotly.Icons.camera,
                click: (gd) => downloadPlot(gd, card.dataset.plotType),
            }],
        });
    } catch (error) {
        logErrorInConsole(error);
        Plotly.purge(plotElt);
        showPlotCardMessage(card, "This plot could not be displayed");
    }
};

/**
 * Shows a message in a plot card in place of its plot, and flags its tab with a warning icon.
 *
 * @param {HTMLElement} card - The plot card.
 * @param {string} message - The message to show.
 */
const showPlotCardMessage = (card, message) => {
    const messageElt = card.querySelector(".plot-card-message");
    messageElt.textContent = message;
    messageElt.classList.remove("is-hidden");

    const tab = document.querySelector(`#plot-tabs li[data-tab="${card.id}"]`);
    tab?.querySelector(".plot-tab-warning").classList.remove("is-hidden");
    tab?.querySelector("a").setAttribute("title", message);
};

/**
 * Downloads a plot as a PNG (drawn in the browser by Plotly) or, if chosen in the advanced
 * plotting options, as a PDF rendered on the server at the plot's current on-screen size.
 *
 * @param {HTMLElement} plotElt - The Plotly plot element.
 * @param {string} plotType - The plot type (key of PLOT_TYPES).
 */
const downloadPlot = async (plotElt, plotType) => {
    const { width, height } = plotElt._fullLayout;
    const filename = `${renderedPlotParams.filename.replace(/\.parquet$/, "")}_${plotType}`;

    if (!document.getElementById("download-plots-pdf").checked) {
        await Plotly.downloadImage(plotElt, { format: "png", width, height, filename });
        return;
    }

    createToast("Preparing PDF download...", "is-info");
    try {
        const { data, headers } = await apiCallsMixin.fetchDominoPlotImage({
            ...renderedPlotParams,
            plots: [plotType],
            image_format: "pdf",
            width: Math.round(width),
            height: Math.round(height),
        });

        // Errors come back as JSON rather than a PDF
        if (data.type !== "application/pdf") {
            const error = JSON.parse(await data.text());
            createToast(error.message || "There was an error creating the PDF");
            return;
        }

        const disposition = headers["content-disposition"] || "";
        const link = document.createElement("a");
        link.href = URL.createObjectURL(data);
        link.download = disposition.match(/filename="([^"]+)"/)?.[1] || `${filename}.pdf`;
        link.click();
        // Release the file once the browser has had time to start the download
        setTimeout(() => URL.revokeObjectURL(link.href), 1000);
    } catch (error) {
        logErrorInConsole(error);
        createToast("There was an error creating the PDF");
    }
};

/**
 * Removes all plots and their tabs.
 */
const clearPlots = () => {
    const panes = document.getElementById("plot-tab-panes");
    for (const plotElt of panes.querySelectorAll(".plot-card-plot")) {
        Plotly.purge(plotElt);
    }
    panes.replaceChildren();
    document.querySelector("#plot-tabs ul").replaceChildren();
    pendingPlots.clear();
    document.getElementById("result-panel-grid").classList.add("is-hidden");
};

/**
 * Builds a share URL that reopens this page with the given plot parameters.  These are
 *  read back by parseURLParams.
 *
 * @param {Object} params - The plot parameters.
 * @returns {string} - The URL string.
 */
const buildShareURL = (params) => {
    const url = new URL("/cell_cell.html", window.location.origin);
    url.searchParams.append("domino_file", params.filename);

    for (const config of PARAMETER_SELECTS) {
        if (params[config.param]) {
            url.searchParams.append(config.param, config.multiple ? params[config.param].join(",") : params[config.param]);
        }
    }

    url.searchParams.append("plots", params.plots.join(","));
    url.searchParams.append("exp_range_threshold", params.exp_range_threshold);
    url.searchParams.append("exp_max_threshold", params.exp_max_threshold);

    if (params.river_apply_thresholds) {
        url.searchParams.append("river_apply_thresholds", "1");
    }

    // Advanced plotting options, only when changed from their defaults
    if (Number(params.dot_size_scale) !== 1) {
        url.searchParams.append("dot_size_scale", params.dot_size_scale);
    }
    if (params.dot_white_background) {
        url.searchParams.append("dot_white_background", "1");
    }

    return url.toString();
};

/**
 * Parses the URL parameters, restoring the plot types, thresholds and selections.
 *
 * @returns {string|null} - The DominoSignal file passed in the URL, if any.
 */
const parseURLParams = () => {
    for (const config of PARAMETER_SELECTS) {
        const value = getUrlParameter(config.param);
        if (value) {
            urlSelections[config.param] = config.multiple ? value.split(",") : [value];
        }
    }

    const plots = getUrlParameter("plots");
    if (plots) {
        const plotTypes = plots.split(",");
        for (const elt of document.querySelectorAll(".plot-type-toggle")) {
            elt.checked = plotTypes.includes(elt.value);
        }
    }

    expRangeThreshold.value = getUrlParameter("exp_range_threshold") ?? expRangeThreshold.value;
    expMaxThreshold.value = getUrlParameter("exp_max_threshold") ?? expMaxThreshold.value;
    riverApplyThresholds.checked = getUrlParameter("river_apply_thresholds") === "1";

    dotSizeScale.value = getUrlParameter("dot_size_scale") ?? dotSizeScale.value;
    updateDotSizeScaleLabel();
    dotWhiteBackground.checked = getUrlParameter("dot_white_background") === "1";

    return getUrlParameter("domino_file");
};

/**
 * Handles the UI updates specific to the page after login.
 * @param {Event} event - The event object.
 * @returns {Promise<void>} - A promise that resolves when all UI updates are completed.
 */
const handlePageSpecificLoginUIUpdates = async (event) => {
    // Set the page header title
    document.getElementById("page-header-label").textContent = "Cell-Cell Communication";

    const dominoFile = parseURLParams();
    await fetchDominoFiles();

    // If a file was passed in the URL, select it and generate its plots
    if (dominoFile && Array.from(fileSelector.options).some((option) => option.value === dominoFile)) {
        fileSelector.value = dominoFile;
        await loadDominoOptions(dominoFile);
        showVisualizationsButton.click();
    }
};
registerPageSpecificLoginUIUpdates(handlePageSpecificLoginUIUpdates);

// Pre-initialize some stuff
await initCommonUI();
